function init(SHELL, INTERFACE, ENGINE, AIRTOWER, prejoinedRoomData)
{
   this._visible = false;
   iglooContext = new com.clubpenguin.igloo.IglooContext(SHELL,INTERFACE,ENGINE,AIRTOWER,this,SHELL.getClientPath(),SHELL.getContentPath(),prejoinedRoomData);
}
function destroy()
{
   trace("[Igloo::main_new.as] destroying context");
   iglooContext.destroy();
   delete iglooContext;
   iglooContext = null;
}
var iglooContext;
if(this == _root)
{
   init();
}
